-- Script: 034-toma-inventario.sql
-- Módulo: 28 - TomaInventario
-- Responsable: Maxi

CREATE TABLE "TomasInventario" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "AlmacenId" integer NOT NULL,
    "FechaToma" timestamp with time zone NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "Responsable" character varying(100) NOT NULL,
    "Observaciones" character varying(500),
    CONSTRAINT "PK_TomasInventario" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TomasInventario_Almacenes_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacenes" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_TomasInventario_Codigo" ON "TomasInventario" ("Codigo");
CREATE UNIQUE INDEX "IX_TomasInventario_Codigo_Normalizado" ON "TomasInventario" (lower(btrim("Codigo")));
CREATE INDEX "IX_TomasInventario_AlmacenId" ON "TomasInventario" ("AlmacenId");
CREATE INDEX "IX_TomasInventario_Estado" ON "TomasInventario" ("Estado");

CREATE TABLE "DetallesTomaInventario" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "TomaInventarioId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "StockSistema" integer NOT NULL,
    "CantidadContada" integer NOT NULL,
    "Diferencia" integer NOT NULL,
    "Observacion" character varying(250),
    CONSTRAINT "PK_DetallesTomaInventario" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DetallesTomaInventario_TomasInventario_TomaInventarioId" FOREIGN KEY ("TomaInventarioId") REFERENCES "TomasInventario" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_DetallesTomaInventario_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_DetallesTomaInventario_TomaInventarioId_ProductoId" ON "DetallesTomaInventario" ("TomaInventarioId", "ProductoId");
CREATE INDEX "IX_DetallesTomaInventario_ProductoId" ON "DetallesTomaInventario" ("ProductoId");
